{"id": "missing_facts-01", "type": "missing_facts", "question": "Candidate has 5 years of public school teaching in Tennessee and wants a NC Continuing Professional License. Which path applies and what do they still need?", "license_types": ["Continuing Professional License", "Out-of-state"], "facts_given": ["5 years public school teaching experience", "Teaching in Tennessee", "Applying for NC CPL"], "missing_fact": "Whether the Tennessee credential is a current, valid professional-level license (not expired, provisional, or temporary).", "notes": "Path depends on the level of the out-of-state credential, which isn't stated."}
{"id": "missing_facts-02", "type": "missing_facts", "question": "RL year 2, BS in biology. Can they renew the RL?", "license_types": ["Residency License"], "facts_given": ["Residency License", "Year 2 of RL", "BS in biology"], "missing_fact": "Whether they have passed the required NC licensure content test for their area.", "notes": "Terse query. Renewal eligibility likely hinges on the test status."}
{"id": "missing_facts-03", "type": "missing_facts", "question": "A teacher with a BS in English is teaching Spanish I on a lateral basis for the rest of the year. Is that allowed and for how long?", "license_types": ["Lateral entry", "Add-on licensure"], "facts_given": ["BS in English", "Teaching Spanish I", "Lateral basis"], "missing_fact": "Whether the teacher holds any NC license with a Spanish or world language area, or has any Spanish coursework or test.", "notes": "Out-of-field assignment rules depend on existing endorsements."}
{"id": "missing_facts-04", "type": "missing_facts", "question": "Candidate wants an emergency license for a math vacancy. Eligible?", "license_types": ["Emergency License"], "facts_given": ["Applying for emergency license", "Math vacancy"], "missing_fact": "Whether the candidate holds a bachelor's degree.", "notes": "Terse. Degree status is a basic eligibility gate."}
{"id": "missing_facts-05", "type": "missing_facts", "question": "CPL renewal due in June. Has 7 CEUs. Good to renew?", "license_types": ["Continuing Professional License"], "facts_given": ["CPL renewal due June", "7 CEUs earned"], "missing_fact": "How many of those CEUs fall in the required content areas for this renewal cycle, and whether they were earned within the cycle window.", "notes": "Terse. Total CEU count alone may not decide renewal."}
{"id": "missing_facts-06", "type": "missing_facts", "question": "Teacher earned NBPTS certification in 2019. License expires next year. Does the national board cert affect renewal?", "license_types": ["Continuing Professional License", "National Board Certification"], "facts_given": ["NBPTS certification earned 2019", "License expires next year"], "missing_fact": "Whether the National Board certificate is still current (not expired or lapsed) as of now.", "notes": "The certificate's current status isn't stated."}
{"id": "missing_facts-07", "type": "missing_facts", "question": "Holds a Permit to Teach, has a bachelor's, wants to teach two more years. Can the permit be renewed?", "license_types": ["Permit to Teach"], "facts_given": ["Permit to Teach", "Bachelor's degree", "Wants two more years"], "missing_fact": "How many years the candidate has already held the permit and whether they've been enrolled in a required program.", "notes": "Permit term limits depend on prior years held."}
{"id": "missing_facts-08", "type": "missing_facts", "question": "Applicant from Georgia, 2 years of teaching, needs NC license. What do they qualify for?", "license_types": ["Out-of-state", "Initial Professional License"], "facts_given": ["Georgia applicant", "2 years teaching experience"], "missing_fact": "The level and validity of the Georgia license (professional, induction, or other) and the teaching area.", "notes": "Out-of-state reciprocity depends on the license level."}
{"id": "missing_facts-09", "type": "missing_facts", "question": "Teacher's CPL lapsed three years ago. Taught four years before that. What's the reinstatement process?", "license_types": ["Continuing Professional License", "Reinstatement"], "facts_given": ["CPL lapsed 3 years ago", "4 years teaching before lapse"], "missing_fact": "Whether the teacher has held any other NC license or taught in another state during the lapse period.", "notes": "Reinstatement pathway can depend on interim activity."}
{"id": "missing_facts-10", "type": "missing_facts", "question": "School counselor candidate, master's in school counseling, 2 years experience. What NC license do they need?", "license_types": ["School Counselor", "School Services Personnel"], "facts_given": ["Master's in school counseling", "2 years experience"], "missing_fact": "Whether the master's program was an approved school counseling program and whether they hold a current NC teaching license.", "notes": "Program approval and prior licensure can both matter."}
{"id": "missing_facts-11", "type": "missing_facts", "question": "CTE welding instructor, 8 yrs industry. Cert?", "license_types": ["Career and Technical Education"], "facts_given": ["CTE welding instructor", "8 years industry experience"], "missing_fact": "Whether they hold a bachelor's degree and any current industry credential or certification.", "notes": "Terse. CTE pathways often differ by degree and credential status."}
{"id": "missing_facts-12", "type": "missing_facts", "question": "Teacher has an Initial Professional License in elementary ed and wants the EC general curriculum add-on. Doable?", "license_types": ["Initial Professional License", "Exceptional Children add-on"], "facts_given": ["IPL in elementary education", "Wants EC general curriculum add-on"], "missing_fact": "How many EC coursework credits or required EC preparation the teacher has already completed.", "notes": "Add-on requirements depend on existing EC coursework."}
{"id": "missing_facts-13", "type": "missing_facts", "question": "Assistant principal candidate has a master's in ed leadership and 3 years teaching. What's needed for a principal license?", "license_types": ["Administrator", "Principal License"], "facts_given": ["Master's in education leadership", "3 years teaching experience", "Seeking principal license"], "missing_fact": "Whether the candidate holds a current NC professional teaching license and the number of years of school-level administrative experience.", "notes": "Administrator licensure depends on both prior licensure and administrative experience."}
{"id": "missing_facts-14", "type": "missing_facts", "question": "Preschool teacher with BS in child development wants to lateral-enter Birth-K. Eligible?", "license_types": ["Birth-Kindergarten", "Lateral entry"], "facts_given": ["Preschool teacher", "BS in child development", "Wants lateral entry to Birth-K"], "missing_fact": "Whether the candidate holds any current NC teaching license or has completed a teacher preparation program.", "notes": "Lateral entry eligibility may hinge on prior preparation."}
{"id": "missing_facts-15", "type": "missing_facts", "question": "PTT expired 2 months ago. Can they reinstate?", "license_types": ["Permit to Teach", "Reinstatement"], "facts_given": ["Permit to Teach expired 2 months ago"], "missing_fact": "Whether the candidate has been employed under another NC license or permit since it expired.", "notes": "Terse. Intervening licensure can change the reinstatement route."}
{"id": "missing_facts-16", "type": "missing_facts", "question": "Candidate has an MLS from a university, applying for NC media coordinator. Is that enough?", "license_types": ["Media Coordinator", "School Services Personnel"], "facts_given": ["MLS from a university", "Applying for media coordinator"], "missing_fact": "Whether the MLS program was accredited by the American Library Association.", "notes": "Program accreditation is the key gate for media licensure."}
{"id": "missing_facts-17", "type": "missing_facts", "question": "Teacher on a limited license for a special subject, 3 years in. Can they keep renewing it?", "license_types": ["Limited License"], "facts_given": ["Limited license for special subject", "3 years in"], "missing_fact": "Whether the employing district has requested renewal and the specific subject area covered.", "notes": "Limited license renewals depend on employer request and subject."}
{"id": "missing_facts-18", "type": "missing_facts", "question": "International applicant, bachelor's from India, 6 years teaching math there, wants NC license. Next steps?", "license_types": ["International applicant", "Initial Professional License"], "facts_given": ["Bachelor's from India", "6 years teaching math in India", "Applying for NC license"], "missing_fact": "Whether the foreign credentials and transcripts have been evaluated and whether they hold a valid teaching credential in India.", "notes": "Credential evaluation and home-country licensure both matter."}
{"id": "missing_facts-19", "type": "missing_facts", "question": "RL teacher, passed Praxis, 2 yrs in. Upgrade to IPL?", "license_types": ["Residency License", "Initial Professional License"], "facts_given": ["Residency License", "Passed Praxis", "2 years teaching"], "missing_fact": "Whether the teacher has completed the required RL support or induction program and any other RL-to-IPL requirements.", "notes": "Terse. Test and years alone may not satisfy the upgrade."}
{"id": "missing_facts-20", "type": "missing_facts", "question": "Teacher has a CPL in science and wants to add math 6-9. How many credits?", "license_types": ["Continuing Professional License", "Add-on licensure"], "facts_given": ["CPL in science", "Wants math 6-9 add-on"], "missing_fact": "Whether the teacher holds a math-related degree, math coursework, or has passed the math content test.", "notes": "Add-on credit requirements depend on existing math preparation."}
